CREATE FUNCTION public.document_chunks_tsv() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.tsv := to_tsvector('simple', unaccent(coalesce(NEW.content,'') || ' ' || coalesce(NEW.breadcrumb,'')));
  RETURN NEW;
END
$$;


